-- BACKLOG ROOT CAUSES (2026-10-13, pillar autonomy; owner 2026-10-13: "Audit and remediate all related failure modes and root causes
-- systemwide across the fleet"). The open-issue audit (125 open, 97 critical or high) found the largest blocked group (about 25 issues
-- with a code-task line) waiting behind code-loop tasks that held their files: two session agents were refused the claim on
-- qnfo-fleet-dashboard and scripts/continuity_snapshot.py by queued, unstarted tasks (issue 2491), and the tasks that had started kept
-- retrying failed edits for hours on the same monolith files (idea-hub 7 attempts "edits overlap", continuity_snapshot 7 attempts
-- "SYNTAX_ERROR", research-exec and the dashboard 4 attempts each failing their suites). Two failure modes, each with a detector:
--   code-task-claim-held-unstarted: fixed by qnfo-code-orchestrator 0.14.5-claim-at-run (PR 1177): the claim is taken at the first step.
--   code-task-retry-holds-file: a task past 6 attempts is still queued and holding its file; remediation is the code-loop success work
--   (issues 1834, 2067, 2506) and sessions taking the file over when the claim lapses.
-- Idempotent (INSERT OR IGNORE). Contracts are created active and due now.
-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: DELETE FROM remediation_contracts WHERE class IN ('fm-code-task-claim-held-unstarted', 'fm-code-task-retry-holds-file'); DELETE FROM failure_modes WHERE fm_key IN ('code-task-claim-held-unstarted', 'code-task-retry-holds-file');
INSERT OR IGNORE INTO failure_modes (fm_key, failure_mode, root_cause, remediation, detector, probe_class, first_seen, issue_id, trigger_condition, symptom, blast_radius) VALUES
 ('code-task-claim-held-unstarted', 'a queued code task that has not started holds the work claim on its file for hours', 'qnfo-code-orchestrator took and renewed the file claim at queue time, not when the task ran', 'qnfo-code-orchestrator 0.14.5-claim-at-run (PR 1177): claim at the first step, never renewed for a queued task, stale unstarted claims released', 'no queued code task with 0 attempts is older than 3 hours', 'fm-code-task-claim-held-unstarted', '2026-10-13', 2491, 'a claim acquired before the holder starts work', 'sessions refused the claim on a file whose code task never started', 'every worker file with a queued code task'),
 ('code-task-retry-holds-file', 'a code task keeps retrying a failing edit for hours while it holds the file, so no session or other task can fix that worker', 'the retry ladder allows up to 9 attempts with 1 h and 2 h backoffs on the same file, and the claim is renewed on every attempt; edits fail on overlapping SEARCH blocks, syntax errors and failing suites', 'raise the per-attempt success of the code loop (issues 1834, 2067, 2506) and release the claim between failed attempts; sessions take the file over when the claim lapses', 'no queued code task has 6 or more attempts', 'fm-code-task-retry-holds-file', '2026-10-13', 1834, 'a long retry ladder on a monolith worker file', 'idea-hub and scripts/continuity_snapshot.py held for 12 hours by tasks at 7 failed attempts', 'qnfo-research-exec, idea-hub, qnfo-social, qnfo-fleet-dashboard and the scripts they share');
INSERT OR IGNORE INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, next_due_at, module, budget_ms, max_items, requires_container) VALUES
 ('fm-code-task-claim-held-unstarted', NULL, 'CLAIM-AT-RUN-1', 'failure-mode detector', 'SELECT ''0'' AS expected, CAST((SELECT COUNT(*) FROM code_tasks WHERE status = ''queued'' AND COALESCE(attempts, 0) = 0 AND created_at < strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-3 hours'')) AS TEXT) AS observed', 'd1-query', 3, 'qnfo-code-orchestrator', 1, 'active', strftime('%Y-%m-%d %H:%M:%S', 'now'), 'failure-mode', 45000, 5, 0),
 ('fm-code-task-retry-holds-file', NULL, 'CODE-LOOP-SUCCESS', 'failure-mode detector', 'SELECT ''0'' AS expected, CAST((SELECT COUNT(*) FROM code_tasks WHERE status = ''queued'' AND COALESCE(attempts, 0) >= 6) AS TEXT) AS observed', 'd1-query', 3, 'qnfo-code-orchestrator', 1, 'active', strftime('%Y-%m-%d %H:%M:%S', 'now'), 'failure-mode', 45000, 5, 0);
